Minimal Test Case:
UNWIND range(1, 50) AS i CREATE (:VLP {id: i});
MATCH (a:VLP), (b:VLP) WHERE a.id <> b.id CREATE (a)-[:NEXT]->(b);
MATCH p=(:VLP)-[*1..10]->(:VLP) RETURN collect(p);

MATCH (n) DETACH DELETE n;
CREATE (n:Paper {published: true});
MATCH (n1:Paper) WITH n1, duration({ hours: n1.published }) AS v1 RETURN n1;

MATCH (n) DETACH DELETE n;
UNWIND range(1, 300) AS i CREATE (:Node {id: i});
WITH 1 AS dummy MATCH (n1:Node), (n2:Node) CREATE (n1)-[:REL]->(n2);
MATCH (n1:Node)-[:REL]->(n2:Node)<-[:REL]-(n3:Node) RETURN collect(n2) LIMIT 1000;
